if (order && event.event_type === "PAYMENT.CAPTURE.COMPLETED") {
  order.status = "paid";
  order.captureId = event.resource.id;
} else if (order && event.event_type === "PAYMENT.CAPTURE.PENDING" && order.status !== "paid" && order.status !== "refunded") {
  // Funds not credited yet (eCheck, review, receiving preferences); wait for
  // PAYMENT.CAPTURE.COMPLETED. Events can arrive out of order, so never
  // downgrade an order that is already paid or refunded.
  order.status = "pending";
  order.captureId = event.resource.id;
}
